import csv, os
files = sorted(os.listdir('.'))
print("FILES:", files)
for f in files:
    if f.endswith('.csv'):
        print("="*25, f)
        try:
            with open(f) as fh:
                r = list(csv.reader(fh))
            for row in r[:5]:
                print(row)
            print("... rows:", len(r))
        except Exception as e:
            print("ERR", e)
